import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CegG7-6m.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1788654326000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>CALDAV_URL</code></td><td>yes</td><td>—</td><td>Root of the CalDAV server, e.g. <code>https://dav.example.net</code>. A calendar collection URL works too and limits this server to that one calendar</td></tr><tr><td><code>CALDAV_USERNAME</code></td><td>yes¹</td><td>—</td><td>Account name</td></tr><tr><td><code>CALDAV_PASSWORD</code></td><td>yes¹</td><td>—</td><td>Password, or an app-specific password where the provider offers one. Deleted from the environment once read</td></tr><tr><td><code>CALDAV_TOKEN</code></td><td>yes¹</td><td>—</td><td>Bearer token instead of username and password. Never both — a configuration carrying both is refused at startup</td></tr><tr><td><code>CALDAV_CALENDARS</code></td><td>no</td><td>every calendar the account can see</td><td>Comma-separated calendars this server may touch, by full path or by final path segment</td></tr><tr><td><code>CALDAV_TIMEZONE</code></td><td>no</td><td><code>UTC</code></td><td>IANA zone for timestamps that carry no offset, e.g. <code>Europe/Berlin</code></td></tr><tr><td><code>CALDAV_USER_EMAIL</code></td><td>no</td><td>the principal&#39;s address set</td><td>The address you are invited as, so <code>respond_to_event</code> can find your own attendee line</td></tr><tr><td><code>CALDAV_MAX_EVENTS</code></td><td>no</td><td><code>100</code></td><td>Entries a listing returns by default, 1–500</td></tr><tr><td><code>CALDAV_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td><code>true</code> registers only the read tools</td></tr><tr><td><code>CALDAV_ALLOW_TOOLS</code></td><td>no</td><td>—</td><td>Tool names, <code>list_*</code> prefixes or <code>essential</code>; only these register</td></tr><tr><td><code>CALDAV_DENY_TOOLS</code></td><td>no</td><td>—</td><td>Same syntax; subtracted from whatever the allow list left</td></tr><tr><td><code>CALDAV_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td><code>true</code> accepts a self-signed certificate, on the configured host only</td></tr><tr><td><code>CALDAV_ALLOW_PLAINTEXT</code></td><td>no</td><td><code>false</code></td><td><code>true</code> allows a plain <code>http://</code> URL to a host that is not loopback, which sends the credentials unencrypted on every request. Otherwise such a URL refuses to start</td></tr><tr><td><code>ELICITATION</code></td><td>no</td><td><code>true</code></td><td><code>false</code> replaces the approval dialog with the two-call token. <strong>Not prefixed</strong></td></tr></tbody></table><p>¹ Either <code>CALDAV_USERNAME</code> + <code>CALDAV_PASSWORD</code>, or <code>CALDAV_TOKEN</code>. Most CalDAV servers speak Basic authentication and want the first pair; the token exists for the deployments that put a bearer-token proxy in front of one. There is no OAuth flow here and nothing resembling a scope: what the account can do, this server can do, which is why an app-specific password is worth using where the provider offers one.</p><p><strong>Every one of these is a secret or shapes what a secret can reach.</strong> The booleans are read strictly where a <code>true</code> removes a protection (<code>CALDAV_INSECURE_TLS</code>, <code>CALDAV_ALLOW_PLAINTEXT</code> accept the exact string <code>true</code> and nothing else) and tolerantly where it turns one on (<code>CALDAV_READ_ONLY</code> also takes <code>1</code>, <code>yes</code>, <code>TRUE</code>). A typo should never quietly remove a safeguard.</p><p>The credentials are deleted from <code>process.env</code> as soon as they are read, before any branch that can exit — so a crash reporter, a child process or a later <code>printenv</code> finds nothing. That is also why they cannot be re-read at runtime.</p><h2 id="elicitation" tabindex="-1"><code>ELICITATION</code> <a class="header-anchor" href="#elicitation" aria-label="Permalink to “ELICITATION”">​</a></h2><p>Whether a client that <em>can</em> show a dialog is asked before a guarded tool acts. <code>false</code> takes the two-call-token path instead — it does not remove the guard, and a server started with it off prints one line saying so.</p><p>Two ways it differs from every other variable here:</p><ul><li><strong>No prefix.</strong> One <code>export ELICITATION=false</code> reaches every MCP server in the same environment, not just this one. That is the point of it and also its risk; see <a href="/guide/approval">Asking a person</a>.</li><li><strong>Fatal on anything else.</strong> Where the <code>CALDAV_*</code> booleans fail <em>off</em> on a typo, this one stops the server with exit code 1. It is the only variable here that defaults to <em>on</em>, and a typo that fell back would leave the dialog running while you believed it was off.</li></ul><p>Values are trimmed and matched case-insensitively. It is read <em>after</em> the credentials are deleted from <code>process.env</code>, so the fatal path cannot leave one sitting there for a crash reporter.</p><h2 id="narrowing-the-tool-list" tabindex="-1">Narrowing the tool list <a class="header-anchor" href="#narrowing-the-tool-list" aria-label="Permalink to “Narrowing the tool list”">​</a></h2><p><code>CALDAV_ALLOW_TOOLS</code> and <code>CALDAV_DENY_TOOLS</code> are comma-separated. Each entry is either an exact tool name or a prefix with a single trailing <code>*</code>:</p><table tabindex="0"><thead><tr><th>Value</th><th>Registers</th></tr></thead><tbody><tr><td><code>essential</code></td><td>the curated preset, marked in the <a href="/reference/tools">tool reference</a></td></tr><tr><td><code>list_events,get_event,create_event</code></td><td>exactly those</td></tr><tr><td><code>list_*</code></td><td>every tool whose name starts with <code>list_</code></td></tr><tr><td><code>*</code></td><td>everything — the same as leaving it unset</td></tr></tbody></table><p>Entries are trimmed and matched case-insensitively; empty entries are ignored, and a value that is empty or only whitespace counts as unset — <code>CALDAV_ALLOW_TOOLS=</code> in a compose file does not mean &quot;allow nothing&quot;. <code>essential</code> is recognised only in the allow list.</p><p><strong>An entry that matches no tool aborts startup</strong>, naming the entry and listing the valid names, as does a malformed pattern such as <code>*_thing</code> or <code>list_*_x</code>. The alternative — ignoring the entry — leaves a tool missing from <code>tools/list</code> with nothing pointing at the cause. If both lists together remove everything, the server refuses to start rather than offering an empty tool list.</p><p>Under <code>CALDAV_READ_ONLY</code>, an exact write-tool name in the allow list is an error naming the read-only setting rather than &quot;unknown tool&quot;; a pattern covering write tools is accepted and merely contributes nothing, with a warning on stderr. Deny entries are exempt: denying an already-suppressed tool is how a defensive list is written.</p>`,16)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};